"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["28033"],{30034(e){e.exports=JSON.parse('{"id":"FIN-1219","slug":"purchasing-managers-index","term":"Purchasing Managers\' Index (PMI)","also_known_as":["PMI"],"difficulty":"Advanced","definition":"The Purchasing Managers\' Index (PMI) is a monthly economic indicator based on surveys of purchasing managers at companies, showing whether business conditions in manufacturing or services are improving or worsening.","explanation":["PMI surveys ask purchasing managers whether key measures, such as new orders, output, employment, supplier delivery times and inventories, have increased, decreased or stayed the same compared with the previous month. The answers are combined into an index.","A reading above 50 indicates that activity is expanding compared with the previous month, while a reading below 50 indicates it is contracting. For example, a manufacturing PMI of 53 suggests factory activity is growing, while a reading of 47 suggests it is shrinking.","PMIs are widely followed because they are released early each month, before most official data, and are seen as leading indicators of economic trends. They are published for many countries and regions, often separately for manufacturing and services.","Because PMIs measure the breadth of change rather than its size, they show the direction of activity more reliably than its exact pace. They are based on surveys, so they can also be affected by sentiment."],"note":"","total":1725,"prev":{"slug":"purchase-price-allocation","term":"Purchase Price Allocation (PPA)"},"next":{"slug":"purchasing-power","term":"Purchasing Power"}}')}}]);